from pathlib import Path
TODAY='2026-06-18'
def header(title): return f"# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n"
def write(path,text): Path(path).write_text(text.strip()+"\n", encoding='utf-8')
def render(title,path,pos,concepts,asks,triage,combined,analysis):
 c='\n\n'.join(f"### {i+1}. {h}\n\n{b}" for i,(h,b) in enumerate(concepts)); a='\n'.join(f"- {x}" for x in asks)
 t='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in triage); cb='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in combined)
 an='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
 write(path, header(title)+f'''## 一句话定位\n\n{pos}\n\n## 一、准确解释：标题里的概念分别是什么\n\n{c}\n\n## 二、药店咨询首先要问什么\n\n{a}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{t}\n\n## 四、品类、咨询口径与即时零售场景\n\n| 品类/服务 | 对应场景 | 药师提醒点 | 平台/药店承接点 |\n|---|---|---|---|\n{cb}\n\n## 五、对平台、药店、药企的业务分析\n\n{an}\n''')

render('儿童用药基础与药店咨询边界','08-疾病与医学基础/补充资料/儿童用药基础与药店咨询边界.md',
'本文回答：儿童用药为什么不能按成人用药缩小剂量处理，药店和即时零售平台应如何设置儿童咨询边界。核心判断是：儿童用药必须同时看年龄、体重、剂型浓度、给药工具、监护人理解和红旗信号，不能把儿童症状搜索直接转化为成人药品推荐。',
[('儿童用药：不是成人剂量简单减少','儿童处于生长发育阶段，药物吸收、代谢、排泄和不良反应风险与成人不同。不同年龄段、体重、剂型、浓度和给药工具都会影响安全性。药店不能按“成人半量”这类经验处理儿童用药。'),('儿童常见症状：高频但变化快','发热、咳嗽、腹泻、皮疹、过敏、疼痛都是儿童高频场景，但儿童表达能力弱，病情变化可能更快。精神状态、进食饮水、尿量、呼吸、脱水和持续高热比单个症状更重要。'),('监护人执行：儿童安全用药的一部分','儿童用药是否安全，取决于监护人能否理解剂量、频次、疗程、禁忌和何时就医。量杯、滴管、混悬液摇匀、不同浓度换算都可能出错。'),('儿童平台推荐：必须先识别年龄和体重','平台不能把儿童搜索词直接导向成人商品，也不能只按销量推荐儿童药。年龄/体重筛选、说明书适用范围和就医提示应前置。')],
['儿童年龄、体重、症状持续时间、精神状态、进食饮水和尿量。','是否发热、呼吸困难、脱水、抽搐、皮疹迅速扩散或持续哭闹。','既往过敏史、基础病、近期用药和是否已经使用退热/止咳/止泻药。','监护人是否能准确量取剂量并理解说明书。','是否婴幼儿、早产儿或存在慢病/免疫低下等高风险情况。'],
[('轻症咨询','症状轻、精神状态好、说明书明确适用','说明书教育、剂型提醒、给药工具提醒','不按成人经验推荐'),('药师重点判断','年龄小、症状反复、已多药使用或剂量不清','核对成分、剂量和禁忌，必要时建议就医','不叠加同类成分'),('优先就医','呼吸困难、抽搐、意识差、严重脱水、持续高热、婴幼儿明显异常','明确提示就医','不引导仅靠自购药处理')],
[('儿童剂型','说明书明确适用年龄/体重','核对浓度、剂量和给药工具','按年龄/体重筛选商品'),('退热/补液/护理用品','常见轻症支持、夜间急用','关注红旗信号和重复成分','附近库存+剂量提示'),('药师咨询','监护人不确定用药','解释说明书、禁忌和就医边界','咨询优先于商品推荐'),('家庭常备','儿童常备用品补货','按年龄段区分，不混用成人药','常备清单和有效期提醒')],
[('平台','儿童入口必须先问年龄和体重，并拦截成人药误用。'),('药店','药师应核对剂型、浓度、剂量和重复成分，尤其是复方感冒药和退热药。'),('药企','儿童产品教育应围绕说明书、给药工具和监护人理解，而不是泛化“儿童可用”。')])

render('孕妇与哺乳期用药咨询边界','08-疾病与医学基础/补充资料/孕妇与哺乳期用药咨询边界.md',
'本文回答：孕妇和哺乳期用药为什么必须单独处理，平台和药店应如何设置咨询边界。核心判断是：孕哺期用药不能按普通成人场景处理，任何药品建议都要先看孕周、哺乳状态、胎儿/婴儿暴露风险、疾病严重程度和医生/药师确认。',
[('孕期用药：风险取决于孕周、药物和疾病本身','孕早期、中晚期和临产前用药风险不同。某些药物可能影响胚胎发育或胎儿安全，但疾病不治疗也可能带来风险。药店不能简单说“孕妇都不能用药”，也不能把“天然”当成安全。'),('哺乳期用药：关注药物进入乳汁和婴儿情况','哺乳期用药要看药物是否进入乳汁、婴儿年龄、是否早产、是否有疾病，以及母亲用药剂量和频次。短期用药、长期用药、外用药和处方药的评估不同。'),('常见小病：在孕哺期也要重新分层','感冒、发热、过敏、腹泻、胃痛、皮肤问题在孕哺期都常见，但药品选择、剂量、禁忌和就医阈值更严格。'),('咨询边界：药店做风险识别，不替代产科/儿科判断','药师可以解释说明书、识别高风险和建议联系医生，但不能替代医生决定复杂用药。平台不应直接用“孕妇可用”标签刺激购买。')],
['孕周、是否哺乳、婴儿年龄和是否早产。','症状是什么、持续多久、严重程度和是否发热/疼痛/感染。','是否已有医生建议，是否正在使用处方药、保健品或中成药。','既往流产、妊娠合并症、肝肾功能异常或过敏史。','是否出现腹痛出血、高热、呼吸困难、严重呕吐或胎动异常。'],
[('轻症咨询','症状轻且说明书明确可咨询','解释说明书、建议医生/药师确认','不随意推荐成人药'),('药师重点判断','孕周特殊、哺乳婴儿小、用药不清','核对风险并建议专业确认','不以经验替代评估'),('优先就医','出血腹痛、高热、严重呕吐、呼吸困难、胎动异常','提示就医','不靠自购药处理')],
[('说明书明确品类','医生/药师确认后使用','核对孕哺期描述和禁忌','强提示确认，不自动推荐'),('外用/局部用品','轻症护理','注意吸收、面积、部位和疗程','按部位和症状分流'),('营养补充','孕期营养管理','避免重复和超量','成分核对和剂量提醒'),('药师咨询','不确定能否用药','以转诊和确认优先','咨询入口优先于商品列表')],
[('平台','孕哺期标签应触发强风险提示，不能直接按成人商品排序。'),('药店','药师应先问孕周、哺乳和婴儿情况，再谈品类。'),('药企','孕哺期内容必须严格遵循说明书和医生/药师确认逻辑，避免“温和安全”泛化表达。')])

render('处方药OTC适应症禁忌症不良反应','08-疾病与医学基础/补充资料/处方药OTC适应症禁忌症不良反应.md',
'本文回答：处方药、OTC、适应症、禁忌症和不良反应这些药品基础概念如何用于药店咨询和平台展示。核心判断是：药品信息不能只讲“治什么”，还必须同时讲“谁不能用”“可能有什么风险”“什么时候应就医”。',
[('处方药与OTC：区别在获取条件和风险管理','处方药需要医生处方或处方流转链路，通常风险更高或需要医生判断；OTC可在说明书范围内自我选择，但并不等于绝对安全。平台有货不代表适合购买，OTC也不能脱离说明书。'),('适应症：药品被批准用于什么情况','适应症说明药品适用于哪些疾病或症状范围。用户觉得“症状像”不等于符合适应症，尤其是症状原因不明、持续加重或特殊人群。'),('禁忌症和慎用：决定哪些人不能简单购买','过敏史、儿童、孕妇、哺乳期、肝肾功能异常、基础病和多药联用都可能影响能否使用。禁忌症是不能使用，慎用是需要更严格评估。'),('不良反应：不是小概率就可以忽略','不良反应包括常见轻微反应，也包括少见但严重风险。药师咨询应提醒用户识别异常反应，并知道什么时候停用、就医或联系医生。')],
['药品是处方药还是OTC，用户是否有医生处方。','用户想解决的症状或疾病是否符合说明书适应症。','是否有过敏、禁忌、特殊人群或多药联用。','是否已经使用同类药或含相同成分的复方药。','是否出现不良反应、疗效不佳或症状加重。'],
[('可自我选择','OTC且说明书适用、无禁忌和红旗信号','说明书教育和药师咨询','不越过适应症'),('药师重点判断','适应症不清、特殊人群、多药联用或复方药','核对禁忌、不良反应和重复成分','不替代医生开方'),('优先就医','严重不良反应、症状加重、处方药无处方','提示就医或医生确认','不继续推荐购买')],
[('OTC','轻症和家庭常备','核对适应症、禁忌和疗程','说明书前置展示'),('处方药','已有诊断和处方','不自行启停或转卖','处方核验和复购提醒'),('说明书教育','用户不理解用法','解释剂量、频次、禁忌和不良反应','内容卡片和药师咨询'),('药师咨询','边界不清或多药联用','做风险分层','商品推荐前置问询')],
[('平台','药品页要同时呈现适应症、禁忌症、不良反应和处方边界，不应只突出功效。'),('药店','药师咨询要从“能卖”转向“是否适合这个用户”。'),('药企','说明书教育是合规内容资产，不应只强调疗效和转化。')])

